description:
Design a simple LED controller that updates two LED outputs based on a clock signal and an enable input. When the enable input (ena) is high, both LED outputs are driven to HIGH; otherwise, the LEDs are in a high-impedance state (floating), effectively turning them off. The LED states are updated on the rising edge of the clock, ensuring synchronous operation.
module top_module(
    input wire clk,          // clock input
    input wire ena,          // enable input
    output wire [1:0] leds   // LED output
);

code:
module top_module(
    input wire clk,          // clock input
    input wire ena,          // enable input
    output wire [1:0] leds   // LED output
);// 1-bit registers
    reg reg0 = 1'b1;
    reg reg1 = 1'b1;

    // update registers on positive edge of clock
    always @(posedge clk) begin
        reg0 <= 1'b1;
        reg1 <= 1'b1;
    end

    // connect registers to 2-bit LED wire
    // control with enable wire
    assign leds[0] = (ena) ? reg0 : 1'bz;
    assign leds[1] = (ena) ? reg1 : 1'bz;

endmodule

