module top_module(
    input clk,
    input areset,  // async active-high reset to zero
    input load,
    input ena,
    input [3:0] data,
    output reg [3:0] q
);reg [3:0] stage1, stage2, stage3, stage4;

always @(posedge clk or posedge areset) begin
    if (areset) begin
        stage1 <= 4'b0;
        stage2 <= 4'b0;
        stage3 <= 4'b0;
        stage4 <= 4'b0;
        q <= 4'b0;
    end else begin
        if (load) begin
            stage1 <= data;
            stage2 <= 4'b0;
            stage3 <= 4'b0;
            stage4 <= 4'b0;
            q <= data;
        end else if (ena) begin
            stage1 <= q;
            stage2 <= stage1;
            stage3 <= stage2;
            stage4 <= stage3;
            if (data[0]) begin
                q <= {stage4[2:0], stage4[3]};
            end else if (data[1]) begin
                q <= {stage4[1:0], stage4[3:2]};
            end else if (data[2]) begin
                q <= {stage4[0], stage4[3:1]};
            end else if (data[3]) begin
                q <= {stage4[3], stage4[2:0]};
            end
        end
    end
end

endmodule

