Implement the Verilog module based on the following description.
Build an 8-bit linear feedback shift register (LFSR) with synchronous active high reset signal. Use a fixed tap sequence for the feedback.
// (1) reset: Resets the LFSR to 8'b00000001 when high.
// (2) q: The value of the LFSR.

module top_module(
    input clk,
    input reset,
    output reg [7:0] q);

code:
module top_module(
    input clk,
    input reset,
    output reg [7:0] q
);

    always @(posedge clk) begin
        if (reset) begin
            // Synchronous reset: Reset the LFSR to 8'b00000001
            q <= 8'b00000001;
        end else begin
            // LFSR with fixed tap sequence
            q <= {q[6:0], q[7] ^ q[5] ^ q[4] ^ q[3]};
        end
    end

endmodule

