module shift_reg_4bit(D, CLK, LOAD, Q);
input [3:0] D;
input CLK;
input LOAD;
output reg [3:0] Q;

always @(posedge CLK) begin
    if (LOAD) begin
        Q <= D;
    end else begin
        Q <= {1'b0, Q[3:1]};
    end
end

endmodule

