	always @(posedge clk) begin
		if (reset) state <= R;
		else state <= next;
	end

	always_comb begin
		case (state)
			R: next = d ? S : R;
			S: next = e ? T1 : T2;
			T1: next = e ? T2 : T3;
			T2: next = e ? T3 : T4;
			T3: next = d ? S : R;
			T4: next = d ? S : R;
			default: next = 'x;
		endcase
	end

	assign w = (state == T2 && !e);

endmodule

