description:
Implement the Verilog module based on the following description.
Build a 4-bit up-down counter with synchronous active low reset signal and an up_down control signal. When the up_down signal is high, the counter increments by 1, otherwise it decrements by 1.
// (1) reset_n: Resets the counter to 4'b0000 when low.
// (2) up_down: Controls the counting direction, increments when high, decrements when low.
// (3) q: The value of the counter.

module top_module(
    input clk,
    input reset_n,
    input up_down,
    output reg [3:0] q);

code:
module top_module(
    input clk,
    input reset_n,
    input up_down,
    output reg [3:0] q
);

    always @(posedge clk) begin
        if (!reset_n) begin
            // Synchronous reset: Reset the counter to 4'b0000
            q <= 4'b0000;
        end else if (up_down) begin
            // Counter increment: Increment by 1 when up_down is high
            q <= q + 1;
        end else begin
            // Counter decrement: Decrement by 1 when up_down is low
            q <= q - 1;
        end
    end

endmodule

