module top_module(clk, oe_e1, a, q);parameter WIDTH = 1;

   input clk;
   input oe_e1;
   input [WIDTH-1:0] a;
   output [WIDTH-1:0] q;

   reg [WIDTH-1:0] oe_r;
   reg [WIDTH-1:0] q_r;
   genvar i;

   generate
      for (i = 0; i < WIDTH; i = i + 1) begin : datapath_bits
         // Define a simple flip-flop as a substitute for enflop_one
         always @(posedge clk) begin
            if (oe_e1) begin
               q_r[i] <= a[i];
            end
         end

         always @(posedge clk) begin
            oe_r[i] <= oe_e1;
         end

         assign q[i] = oe_r[i] ? q_r[i] : 1'bx;
      end
   endgenerate
endmodule

