module top_module(
  input [n-1:0] req,
  input clk,
  input rst,
  output gnt
);parameter n = 4; // number of devices on the bus

  reg [n-1:0] req_priority;
  reg [n-1:0] req_granted;
  reg [n-1:0] req_latched;
  reg [n-1:0] req_valid;
  reg [n-1:0] req_delay;
  reg [n-1:0] req_delayed;
  reg [n-1:0] req_grant;
  reg [n-1:0] req_grant_latched;
  reg [n-1:0] req_grant_valid;

  always @ (posedge clk or posedge rst) begin
    if (rst) begin
      req_priority <= 0;
      req_granted <= 0;
      req_latched <= 0;
      req_valid <= 0;
      req_delay <= 0;
      req_delayed <= 0;
      req_grant <= 0;
      req_grant_latched <= 0;
      req_grant_valid <= 0;
    end
    else begin
      // priority scheme
      req_priority <= req & ~req_valid;

      // latching
      req_latched <= req_priority;

      // valid flag
      req_valid <= req_priority | req_delayed;

      // delay
      req_delay <= req_valid & ~req_granted;
      req_delayed <= req_delay;

      // grant
      req_grant <= req_latched & req_valid;
      req_grant_latched <= req_grant;
      req_grant_valid <= req_grant_latched;

      // granted flag
      req_granted <= req_grant_valid;
    end
  end

  assign gnt = req_granted;

endmodule

