module lfsr #(
    parameter WIDTH = 16,
    parameter POLY = 16'hB400
) (
    input wire clk,
    input wire rst,
    input wire load,
    input wire [WIDTH-1:0] seed,
    output reg [WIDTH-1:0] lfsr_out
);

always @(posedge clk) begin
    if (rst) begin
        lfsr_out <= seed;
