nor NOR0 (temp0, p[0], p[1]);
nor NOR1 (temp1, temp0, p[2]);
nor NOR2 (temp2, temp1, p[3]);
nor NOR3 (temp3, temp2, p[4]);
nor NOR4 (temp4, temp3, p[5]);
nor NOR5 (temp5, temp4, p[6]);
nor NOR6 (temp6, temp5, p[7]);


assign s = temp6;endmodule

