module top_module(A, B, Cin, S, Cout);input [3:0] A, B;
    input Cin;
    output [3:0] S;
    output Cout;

    wire [4:0] C;  // Change to wire [4:0] to accommodate C[4]

    assign C[0] = Cin;

    // Full Adder
    genvar i;
    generate
        for (i = 0; i < 4; i = i + 1) begin : FA
            assign S[i] = A[i] ^ B[i] ^ C[i];
            assign C[i+1] = (A[i] & B[i]) | (A[i] & C[i]) | (B[i] & C[i]);
