module top_module(
    input [3:0] A,
    input [3:0] B,
    input clk,               // Added clk as an input
    output reg [7:0] S       // Changed S to be reg type since we are driving it in always block
);reg [3:0] a_reg, b_reg;
reg [7:0] s_reg;
reg [2:0] stage;
reg [2:0] addr1, addr2, addr3;
reg [7:0] data1, data2, data3;
reg [7:0] result;

// Register file
reg [7:0] reg_file [0:7];

// Initialize stage
initial begin
    stage = 0;
end

// Fetch stage
always @ (posedge clk) begin
    if (stage == 0) begin
        a_reg <= A;
        b_reg <= B;
        stage <= 1;
    end
end

// Decode stage
always @ (posedge clk) begin
    if (stage == 1) begin
        addr1 <= a_reg;
        addr2 <= b_reg;
        stage <= 2;
    end
end

// Execute stage
always @ (posedge clk) begin
    if (stage == 2) begin
        data1 <= reg_file[addr1];
        data2 <= reg_file[addr2];
        result <= data1 * data2;
        stage <= 3;
    end
end

// Memory stage
always @ (posedge clk) begin
    if (stage == 3) begin
        addr3 <= s_reg[7:4]; // Ensure addr3 is valid for a write operation
        data3 <= result;
        stage <= 4;
    end
end

// Write back stage
always @ (posedge clk) begin
    if (stage == 4) begin
        reg_file[addr3] <= data3;
        S <= result; // Changed to assign the output S directly from the result
        stage <= 0;
    end
end

endmodule

